CREATE TABLE IF NOT EXISTS weekly_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, week_start DATE NOT NULL, achievements TEXT DEFAULT '', projects_advanced TEXT DEFAULT '', skills_learned TEXT DEFAULT '', books_pages TEXT DEFAULT '', gym_sessions INTEGER NOT NULL DEFAULT 0, challenges TEXT DEFAULT '', missed_activities TEXT DEFAULT '', improvements TEXT DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id, week_start))